"""Standalone controls over embedded inert exported successor metadata.

The compressed fixture contains only the 42 explicit pre-implementation metadata
bodies. Paths inside those declarations are inert; all test reads use private
rewritten descriptors. It contains no source, model, database, key or Git body.
"""
from __future__ import annotations

import base64
import copy
import json
import os
import tempfile
import unittest
import zlib
from collections import Counter
from pathlib import Path
from unittest.mock import patch

import codebase_ir_full_successor_cohort_audit as tool


def _unpack():
    compressed = base64.b85decode(_FIXTURE_B85.encode("ascii"))
    reader = zlib.decompressobj()
    raw = reader.decompress(compressed, 6 * 1024 * 1024 + 1)
    if len(raw) > 6 * 1024 * 1024 or reader.unconsumed_tail or not reader.eof or reader.unused_data:
        raise AssertionError("bounded inert fixture unpacking")
    return {role: text.encode("utf-8") for role, text in json.loads(raw).items()}


def _set(value, path, replacement):
    for key in path[:-1]:
        value = value[key]
    value[path[-1]] = replacement


class FullSuccessorControls(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.raw = _unpack()

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name)
        self.inputs = self.root / "selected"
        self.inputs.mkdir()
        self.bodies = dict(self.raw)
        self.manifest = dict(schema=tool.INPUT_SCHEMA, selected_files=[])
        for index, role in enumerate(tool.ROLES):
            path = self.inputs / f"{index:03d}-{role}.body"
            path.write_bytes(self.bodies[role])
            self.manifest["selected_files"].append(dict(role=role, path=str(path), sha256=tool.sha(self.bodies[role]), size_bytes=len(self.bodies[role])))
        self.manifest_path = self.inputs / "manifest.json"
        self.write_manifest()
        self.output = self.root / "output"
        self.metadata = {role: tool.document(raw) for role, raw in self.bodies.items()}

    def write_manifest(self):
        self.manifest_path.write_bytes(tool.report_bytes(self.manifest))

    def repaired(self, role, mutate):
        value = copy.deepcopy(self.metadata[role])
        mutate(value)
        if "artifact_cid" in value and "value" in value:
            value["artifact_cid"] = tool.cid(tool.wire(value["value"]), role.startswith("default_page_") or role == "reference_page")
        raw = tool.report_bytes(value)
        self.bodies[role], self.metadata[role] = raw, value
        row = next(row for row in self.manifest["selected_files"] if row["role"] == role)
        Path(row["path"]).write_bytes(raw)
        row.update(sha256=tool.sha(raw), size_bytes=len(raw))
        audit = copy.deepcopy(self.metadata["independent_audit"])
        if role in tool.SELECTORS:
            pin = next(pin for pin in audit["archive"]["files"] if pin["path"] == tool.SELECTORS[role])
            pin.update(sha256=tool.sha(raw), bytes=len(raw))
        elif role == "full_scan_result":
            audit["audited_result"].update(sha256=tool.sha(raw), bytes=len(raw))
        if role != "independent_audit":
            audit_raw = tool.report_bytes(audit)
            self.bodies["independent_audit"], self.metadata["independent_audit"] = audit_raw, audit
            audit_row = next(row for row in self.manifest["selected_files"] if row["role"] == "independent_audit")
            Path(audit_row["path"]).write_bytes(audit_raw)
            audit_row.update(sha256=tool.sha(audit_raw), size_bytes=len(audit_raw))
        self.write_manifest()

    def invoke(self):
        anchors = {role: next(row["sha256"] for row in self.manifest["selected_files"] if row["role"] == role) for role in tool.ANCHORS}
        with patch.object(tool, "ANCHORS", anchors):
            return tool.evaluate(self.manifest_path, self.output)

    def page_control(self, page_index, mutate, message):
        role = f"default_page_{page_index:02d}"
        value = copy.deepcopy(self.metadata[role])
        mutate(value["value"])
        value["artifact_cid"] = tool.cid(tool.wire(value["value"]))
        root = self.metadata["optimized_root"]["value"]
        selection = self.metadata["optimized_selection"]["value"]
        previous = None if page_index == 0 else self.metadata[f"default_page_{page_index - 1:02d}"]["artifact_cid"]
        with self.assertRaisesRegex((tool.Refused, ValueError, TypeError), message):
            tool.page(value, root, selection, page_index * 32, previous)

    def snapshot_control(self, mutate, message):
        envelope = copy.deepcopy(self.metadata["current_manifest"])
        value = envelope["value"]
        mutate(value)
        captured = value["snapshot"]
        for entry in captured["entries"]:
            old = entry["entry_cid"]
            entry["entry_cid"] = tool.object_cid({k: v for k, v in entry.items() if k != "entry_cid"})
            for unit in value["units"]:
                if unit["entry_cid"] == old:
                    unit["entry_cid"] = entry["entry_cid"]
        captured["snapshot_cid"] = tool.object_cid({k: v for k, v in captured.items() if k != "snapshot_cid"})
        head = copy.deepcopy(self.metadata["optimized_selection"]["value"]["current_head"])
        head["snapshot_cid"] = captured["snapshot_cid"]
        head["ast_revision_id"] = "rev:" + head["repository_id"] + ":snapshot:" + head["snapshot_cid"]
        value["ast_revision_id"] = head["ast_revision_id"]
        envelope["artifact_cid"] = head["manifest_cid"] = tool.object_cid(value)
        with self.assertRaisesRegex((tool.Refused, ValueError, TypeError), message):
            tool.snapshot(envelope, head)

    def test_complete_dispositions_and_limits(self):
        report = self.invoke()
        self.assertEqual(report["complete_member_count"], 300)
        self.assertEqual(report["default_page_count"], 10)
        self.assertEqual(report["reference_page_count"], 1)
        self.assertEqual(report["reference_observed_member_count"], 32)
        self.assertEqual(report["default_dispositions"], {"inferred": 205, "deferred_budget": 89, "unsupported_target": 2, "opaque": 2, "parse_failed": 1, "unindexed": 1})
        self.assertEqual(report["current_snapshot"]["coverage"]["semantic_symbols"], 590)
        self.assertEqual(report["source_delta"]["coverage"]["union_entries"], 302)
        self.assertEqual(report["declared_child_role_counts"], {"train": 1, "tune": 1, "canary": 1})
        self.assertEqual([row["disposition"] for row in report["declared_child_roles"]], ["inferred"] * 3)
        self.assertEqual(len(report["selected_files"]), 42)
        self.assertTrue(all(report[field] is True for field in tool.TRUE_FLAGS))
        self.assertTrue(all(report[field] is False for field in tool.FALSE_FLAGS))
        self.assertTrue(all(type(report[field]) is int and report[field] == 0 for field in tool.ZERO_FIELDS))
        self.assertEqual(report["production_tasks_closed"], [])

    def test_only_explicit_metadata_reads(self):
        opened = set()
        original = tool.os.open
        def observed(path, flags, *args, **kwargs):
            path = Path(path)
            self.assertTrue(path.is_relative_to(self.root), "no owner path or declared child recovery")
            opened.add(path)
            return original(path, flags, *args, **kwargs)
        with patch.object(tool.os, "open", observed):
            report = self.invoke()
        selected = {Path(row["path"]) for row in self.manifest["selected_files"]} | {self.manifest_path}
        copies = {Path(row["retained_path"]) for row in report["selected_files"]} | {self.output / "input.json", self.output / "full_successor_cohort_audit.json"}
        self.assertEqual(opened, selected | copies)

    def test_fixed_outer_anchor_refusal(self):
        row = self.manifest["selected_files"][0]
        raw = Path(row["path"]).read_bytes() + b" "
        Path(row["path"]).write_bytes(raw)
        row.update(sha256=tool.sha(raw), size_bytes=len(raw))
        self.write_manifest()
        with self.assertRaisesRegex(tool.Refused, "outer metadata anchor"):
            tool.evaluate(self.manifest_path, self.output)

    def test_manifest_future_field_refused(self):
        self.manifest["future"] = True
        self.write_manifest()
        with self.assertRaisesRegex(tool.Refused, "closed full successor"):
            self.invoke()

    def test_role_reordering_refused(self):
        self.manifest["selected_files"][4:6] = reversed(self.manifest["selected_files"][4:6])
        self.write_manifest()
        with self.assertRaisesRegex(tool.Refused, "ordered metadata role"):
            self.invoke()

    def test_descriptor_boolean_size_refused(self):
        self.manifest["selected_files"][3]["size_bytes"] = True
        self.write_manifest()
        with self.assertRaisesRegex(tool.Refused, "typed exact raw descriptor"):
            self.invoke()

    def test_body_cap_before_open(self):
        self.manifest["selected_files"][3]["size_bytes"] = 2 * tool.MiB + 1
        self.write_manifest()
        original = tool.Reads.bounded
        read = []
        def observed(path, cap):
            read.append(path)
            return original(path, cap)
        with patch.object(tool.Reads, "bounded", staticmethod(observed)), self.assertRaisesRegex(tool.Refused, "preallocation body bound"):
            self.invoke()
        self.assertEqual(read, [self.manifest_path, self.manifest_path])

    def test_selected_symlink_refused(self):
        row = self.manifest["selected_files"][3]
        path = Path(row["path"])
        target = path.with_suffix(".moved")
        path.rename(target)
        path.symlink_to(target)
        with self.assertRaisesRegex(tool.Refused, "canonical selected file"):
            self.invoke()

    def test_selected_fifo_refused(self):
        path = Path(self.manifest["selected_files"][3]["path"])
        path.unlink()
        os.mkfifo(path)
        with self.assertRaisesRegex(tool.Refused, "regular exact selected size"):
            self.invoke()

    def test_hardlink_alias_refused(self):
        path = Path(self.manifest["selected_files"][4]["path"])
        other = Path(self.manifest["selected_files"][3]["path"])
        path.unlink()
        os.link(other, path)
        self.manifest["selected_files"][4].update(sha256=self.manifest["selected_files"][3]["sha256"], size_bytes=self.manifest["selected_files"][3]["size_bytes"])
        self.write_manifest()
        with self.assertRaisesRegex(tool.Refused, "hardlink selected alias"):
            self.invoke()

    def test_duplicate_json_refused(self):
        with self.assertRaisesRegex(tool.Refused, "duplicate JSON"):
            tool.document(b'{"a":1,"a":2}')

    def test_nonfinite_json_refused(self):
        with self.assertRaisesRegex(tool.Refused, "nonfinite JSON"):
            tool.document(b'{"a":NaN}')

    def test_overdeep_json_refused(self):
        with self.assertRaisesRegex(tool.Refused, "structure budget"):
            tool.document(b'{"a":' + b'[' * 66 + b'0' + b']' * 66 + b'}')

    def test_snapshot_positive(self):
        selection = self.metadata["optimized_selection"]["value"]
        rows, summary = tool.snapshot(self.metadata["current_manifest"], selection["current_head"])
        self.assertEqual(len(rows), 300)
        self.assertEqual(summary["coverage"]["ast_failed"], 1)
        self.assertIsNotNone(rows["raw:6d616c666f726d65642e7079"]["member"]["ast_cid"])

    def test_last_page_positive_keeps_frontiers(self):
        root = self.metadata["optimized_root"]["value"]
        selection = self.metadata["optimized_selection"]["value"]
        _, row, members = tool.page(self.metadata["default_page_09"], root, selection, 288, self.metadata["default_page_08"]["artifact_cid"])
        self.assertEqual(row["inferred_rows"], 7)
        self.assertEqual(Counter(item["disposition"] for item in members), Counter({"inferred": 7, "unsupported_target": 2, "opaque": 2, "parse_failed": 1}))


def _page_test(index, path, replacement, message):
    def control(self):
        self.page_control(index, lambda value: _set(value, path, replacement), message)
    return control


