def _repaired_test(role, path, replacement, message):
    def control(self):
        self.repaired(role, lambda value: _set(value, path, replacement))
        with self.assertRaisesRegex((tool.Refused, ValueError, TypeError, KeyError), message):
            self.invoke()
    return control


