def _late_test(kind, stage):
    def control(self):
        reached = []
        def mutate(actual_stage, output):
            if actual_stage != stage:
                return
            reached.append(actual_stage)
            if kind == "original":
                path = Path(self.manifest["selected_files"][0]["path"])
                path.write_bytes(path.read_bytes() + b" ")
            elif kind == "manifest":
                self.manifest_path.write_bytes(self.manifest_path.read_bytes() + b" ")
            elif kind == "copy":
                path = output / "inputs/000-full_scan_result.body"
                path.write_bytes(path.read_bytes() + b" ")
            elif kind == "copy_manifest":
                path = output / "input.json"
                path.write_bytes(path.read_bytes() + b" ")
            elif kind == "report":
                path = output / "full_successor_cohort_audit.json"
                path.write_bytes(path.read_bytes() + b" ")
            elif kind == "extra_file":
                (output / "extra").write_bytes(b"extra")
            elif kind == "extra_directory":
                (output / "extra").mkdir()
            elif kind == "extra_symlink":
                (output / "extra").symlink_to(self.manifest_path)
            elif kind == "root_alias":
                moved = output.with_name("moved")
                output.rename(moved)
                output.symlink_to(moved, target_is_directory=True)
            elif kind == "root_replacement":
                output.rename(output.with_name("moved"))
                output.mkdir()
        with patch.object(tool, "checkpoint", mutate), self.assertRaises((tool.Refused, OSError, ValueError)):
            self.invoke()
        self.assertEqual(reached, [stage])
    return control


for _kind, _stage in (
    ("original", "after_publish"), ("manifest", "after_publish"), ("copy", "after_publish"),
    ("copy_manifest", "after_publish"), ("report", "after_publish_copies"),
    ("extra_file", "after_publish_copies"), ("extra_directory", "after_publish_copies"),
    ("extra_symlink", "after_publish_copies"), ("root_alias", "after_publish_copies"),
    ("root_replacement", "after_publish_copies"),
):
    setattr(FullSuccessorControls, "test_late_" + _kind, _late_test(_kind, _stage))


